SELECT w.ASSIGNMENT_ID, w.APPLICATION_ID, a.APPLICATION_NO, p.FULL_NAME_AR APPLICANT_NAME_AR, a.STATUS_CODE, w.ASSIGNMENT_TYPE, w.ASSIGNED_TO, w.ASSIGNED_BY, w.ASSIGNED_AT, w.DUE_DATE, w.ASSIGNMENT_STATUS, CASE WHEN w.DUE_DATE < TRUNC(SYSDATE) AND w.COMPLETED_AT IS NULL THEN 'Y' ELSE 'N' END OVERDUE_FLAG FROM MFF_WORK_ASSIGNMENTS w JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID = w.APPLICATION_ID JOIN MFF_PERSONS p ON p.PERSON_ID = a.PRIMARY_PERSON_ID WHERE NVL(w.ASSIGNMENT_STATUS,'OPEN') <> 'COMPLETED';
